#!/usr/bin/env python3
"""Offline oracle regeneration; requires benchmark/prepare/requirements.txt."""
import gzip, hashlib, itertools, json, subprocess
from pathlib import Path
import tokenizers
from tokenizers import Regex, pre_tokenizers as pt
ROOT=Path(__file__).resolve().parents[2]
def sha(data): return hashlib.sha256(data).hexdigest()
def pre(expr,split=False): return pt.Split(Regex(expr),'isolated' if split else 'removed',invert=not split)
def spans(p,text):
    offsets=[0]
    for c in text: offsets.append(offsets[-1]+len(c.encode()))
    return [{'Start':offsets[a],'End':offsets[b]} for _,(a,b) in p.pre_tokenize_str(text)]
def main():
    assert tokenizers.__version__=='0.22.2'
    scalars=''.join(chr(c) for c in range(0x110000) if not 0xD800<=c<=0xDFFF)
    tables={}
    for name,expr in [('wordMark',r'[\p{L}\p{M}]+')]:
        tables[name]=[(ord(s[0]),ord(s[-1])) for s,_ in pre(expr).pre_tokenize_str(scalars)]
    lines=['// Code generated by testdata/patterns/generate.py; DO NOT EDIT.','// Unicode membership pinned to tokenizers 0.22.2 native oracle.','package scan','']
    for name,ranges in tables.items():
        lines+=['var '+name+'Ranges = [...]runeRange{']+['{0x%X, 0x%X},'%r for r in ranges]+['}','']
    table=ROOT/'internal/scan/word_tables.go';table.write_text('\n'.join(lines)+'\n')
    subprocess.run(['gofmt','-w',str(table)],check=True)
    cases={json.loads(line)['input'] for line in gzip.decompress((ROOT/'testdata/qwen/cases.jsonl.gz').read_bytes()).splitlines()}
    alphabet=['A','a','ǅ','中','ʰ','\u0301',' ','\n','1','/']
    for n in range(1,5):cases.update(''.join(v) for v in itertools.product(alphabet,repeat=n))
    for ranges in tables.values():
        for lo,hi in ranges:
            for c in (lo-1,lo,hi,hi+1):
                if 0<=c<0x110000 and not 0xD800<=c<=0xDFFF:
                    s=chr(c);cases.update([s,'A'+s+'ABa '+s+s,'\u0301'+s+'\u0301'])
    cases.update(['a  \nb','a\nb','a\n\nb','a \rX','a\r\nb','a  \n  X','a\u2028b'])
    for n in [1,2,3,4,5,6,7,15,16,17,31,32,33,63,64,65,4096]:
        for s in ['1','１',' ','\u2003','A','a','中','\u0301','\n']:
            cases.update([s*n,s*n+'X','x'+s*n+'\nY'])
    for i in [1]:
        d=ROOT/f'testdata/patterns/P{i:02}';m=json.loads((d/'manifest.json').read_text())
        matches,split=pre(m['pattern']),pre(m['pattern'],True)
        raw=b''.join((json.dumps({'input':s,'matches':spans(matches,s),'split':spans(split,s)},ensure_ascii=True,separators=(',',':'))+'\n').encode() for s in sorted(cases))
        data=gzip.compress(raw,mtime=0);(d/'cases.jsonl.gz').write_bytes(data)
        m.update(oracle_version=tokenizers.__version__,oracle_native_sha256=sha((Path(tokenizers.__file__).parent/'tokenizers.abi3.so').read_bytes()),case_count=len(cases),cases_sha256=sha(data),tables_sha256=sha(table.read_bytes()),generator_sha256=sha(Path(__file__).read_bytes()),matches_settings={'behavior':'Removed','invert':True},split_settings={'behavior':'Isolated','invert':False})
        (d/'manifest.json').write_text(json.dumps(m,indent=2)+'\n');print(m['pattern_id'],len(cases),flush=True)
if __name__=='__main__':main()
